sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_pattern;
uniform float amzp_amount;
uniform float amzp_scatter;
uniform float amzp_grain;
uniform float amzp_blur;
uniform float amzp_pScale;
uniform float amzp_pStr;
uniform float amzp_angle;
uniform float amzp_haze;
layout(color) uniform half4 amzp_tint;
uniform float amzp_tintAmt;
uniform float amzp_sparkle;
uniform float amzp_shimmer;
uniform float amzp_clearR;
uniform float amzp_clearX;
uniform float amzp_clearY;
uniform float amzp_clearSoft;
uniform float amzp_seed;
uniform float amzp_overdrawOn;
uniform float amzp_quality;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 at(float2 uv) { return amzTexture(0, l2s(clamp(uv, 0.0, 1.0))); }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.17) * 43758.5453); }
    float2 h2(float2 p) { return float2(hh(p), hh(p + 17.31)); }
    float vn(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hh(i), hh(i + float2(1.0, 0.0)), f.x), mix(hh(i + float2(0.0, 1.0)), hh(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float2 rot(float2 q, float a) { float c = cos(a), s = sin(a); return float2(c * q.x - s * q.y, s * q.x + c * q.y); }
    float3 pat(float2 p) {
        float2 q = rot(p, radians(amzp_angle)) / max(amzp_pScale, 2.0);
        if (int(amzp_pattern) == 1) {
            float2 i = floor(q), f = fract(q);
            float d1 = 9.0, d2 = 9.0;
            float2 best = float2(0.0);
            for (int y = -1; y <= 1; y++) for (int x = -1; x <= 1; x++) {
                float2 g = float2(float(x), float(y));
                float2 o = g + h2(i + g) - f;
                float d = dot(o, o);
                if (d < d1) { d2 = d1; d1 = d; best = o; } else if (d < d2) { d2 = d; }
            }
            float crack = 1.0 - smoothstep(0.0, 0.08, sqrt(d2) - sqrt(d1));
            return float3(rot(normalize(best + 1e-5) * (0.3 + 0.7 * sqrt(d1)), -radians(amzp_angle)), crack);
        }
        if (int(amzp_pattern) == 2) {
            float a = vn(q * 1.3) * 6.2831853;
            float2 o = float2(sin(q.y * 3.1 + vn(q) * 3.0), cos(q.x * 2.7 + vn(q + 5.0) * 3.0));
            return float3(rot(o * 0.8 + float2(cos(a), sin(a)) * 0.2, -radians(amzp_angle)), 0.0);
        }
        if (int(amzp_pattern) == 3) {
            float fx = fract(q.x) - 0.5;
            return float3(rot(float2(fx * 2.0, 0.0), -radians(amzp_angle)), 0.0);
        }
        return float3((vn(q * 2.0) - 0.5) * 0.6, (vn(q * 2.0 + 9.0) - 0.5) * 0.6, 0.0);
    }
    void nmFxMain() {
        float2 W = layer;
        float2 uv = amzLayerNorm();
        float2 p = uv * W;
        float4 src = at(uv);
        float A = max(amzp_amount, 0.0);
        float fm = 1.0;
        if (amzp_clearR > 0.0) {
            float M = min(W.x, W.y);
            float d = length((uv - float2(amzp_clearX, 1.0 - amzp_clearY)) * W) / (amzp_clearR * M);
            fm = smoothstep(1.0 - amzp_clearSoft, 1.0, d);
        }
        A *= fm;
        if (A <= 0.0001) { amzOutput = src; return; }
        float tsh = amzp_shimmer > 0.0 ? floor(time * amzp_shimmer * 12.0) : 0.0;
        float3 pt = pat(p);
        float2 base = pt.xy * amzp_pStr * amzp_pScale * 0.35 * A;
        float n = amzp_quality < 1.5 ? 4.0 : (amzp_quality < 2.5 ? 8.0 : (amzp_quality < 3.5 ? 12.0 : (amzp_quality < 4.5 ? 18.0 : 24.0)));
        float4 acc = float4(0.0);
        float gs = max(amzp_grain, 0.5);
        float2 gc = floor(p / gs);
        for (int i = 0; i < 24; i++) {
            float fi = float(i);
            if (fi >= n) break;
            float2 r = (h2(gc + fi * 13.7 + tsh) - 0.5) * 2.0 * amzp_scatter * A;
            float rr = sqrt((fi + 0.5) / n);
            float aa = fi * 2.399963;
            float2 bd = float2(cos(aa), sin(aa)) * rr * amzp_blur * A;
            acc += at((p + base + r + bd) / W);
        }
        float4 c = acc / n;
        if (int(amzp_pattern) == 1) c.rgb = mix(c.rgb, min(c.rgb + 0.25 * c.a, float3(c.a)), pt.z * amzp_pStr * 0.6 * fm);
        c.rgb = mix(c.rgb, float3(c.a), clamp(amzp_haze * fm, 0.0, 1.0));
        c.rgb = mix(c.rgb, c.rgb * amzp_tint.rgb * 1.15, clamp(amzp_tintAmt * fm, 0.0, 1.0));
        float sp = hh(floor(p / max(gs, 1.0)) + 3.3 + tsh);
        c.rgb += c.a * amzp_sparkle * fm * step(0.985, sp) * (sp - 0.985) * 66.0 * 0.5;
        c.rgb = clamp(c.rgb, 0.0, c.a);
        amzOutput = c;
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
